Explore the top 1000 greatest albums across music history in an interactive sonic constellation and visual archive.

albums = FileAttachment("top_1000_albums.csv").csv({ typed: true })

// Helper to pull the primary genre for grouping and coloring
cleanData = albums.map(d =&gt; ({
  ...d,
  primary_genre: d.genres ? d.genres.split(",")[0].trim() : "other"
}))


















viewof search = Inputs.search(cleanData, {
  placeholder: "Search artist, album, genre, or release year..."
})









genresList = ["All", "rock", "pop", "folk", "electronica", "punk", "hip-hop", "soul", "jazz", "country", "metal"]
viewof genreFilter = Inputs.select(genresList, {
  label: "Genre",
  value: "All"
})


















viewof limit = Inputs.select([48, 96, 240, 1000], {
  label: "Display",
  value: 48
})









// Filter data by both active text search and selected genre
filtered = search.filter(d =&gt; genreFilter === "All" || d.primary_genre === genreFilter)







The Sonic Constellation

// Abstract scatterplot visualizing all 1000 albums by Year and Rating
Plot.plot({
  width: width,
  height: 340,
  style: {
    background: "#121620",
    color: "#cbd5e1",
    borderRadius: "12px",
    padding: "1rem",
    border: "1px solid rgba(255, 255, 255, 0.08)"
  },
  grid: true,
  x: { label: "Release Year →", tickFormat: "" },
  y: { label: "Community Rating (1-5) →" },
  color: {
    scheme: "spectral",
    legend: true
  },
  marks: [
    Plot.dot(filtered, {
      x: "year",
      y: "rating",
      fill: "primary_genre",
      r: 4,
      fillOpacity: 0.8,
      stroke: "#0c0e14",
      strokeWidth: 0.5,
      title: d =&gt; `#${d.rank}: ${d.album}\nArtist: ${d.artist} (${d.year})\nRating: ⭐ ${d.rating}\nGenre: ${d.primary_genre}`
    })
  ]
})







md`*Showing ${Math.min(limit, filtered.length)} of ${filtered.length} matching albums*`







// Abstract visual grid of album covers
html`&lt;div class="album-grid"&gt;
  ${filtered.slice(0, limit).map(d =&gt; html`
    &lt;div class="album-card"&gt;
      &lt;div class="album-cover-wrap"&gt;
        &lt;img class="album-cover-img" src="${d.image_url}" alt="${d.album}" loading="lazy" /&gt;
        &lt;span class="album-badge"&gt;#${d.rank}&lt;/span&gt;
      &lt;/div&gt;
      &lt;div class="album-info"&gt;
        &lt;div class="album-title" title="${d.album}"&gt;${d.album}&lt;/div&gt;
        &lt;div class="album-artist" title="${d.artist}"&gt;${d.artist} (${d.year})&lt;/div&gt;
        &lt;div class="album-meta"&gt;
          &lt;span&gt;⭐ ${d.rating.toFixed(2)}&lt;/span&gt;
          &lt;span style="color: #64748b; text-transform: capitalize;"&gt;${d.primary_genre}&lt;/span&gt;
        &lt;/div&gt;
      &lt;/div&gt;
    &lt;/div&gt;
  `)}
&lt;/div&gt;`
